<script setup lang="ts">
import{computed,ref}from'vue';import{onLoad,onPullDownRefresh}from'@dcloudio/uni-app';import WareState from '@/shared/components/WareState.vue';import{cartonInventoryApi,type CartonOptions,type InventoryTrace}from'../../api/carton-inventory.api';
const kind=ref<'inbound'|'outbound'>('inbound'),list=ref<InventoryTrace[]>([]),options=ref<CartonOptions>({skus:[],parts:[]}),skuId=ref(0),part=ref(''),start=ref(''),end=ref(''),loading=ref(true),error=ref(''),detail=ref<InventoryTrace|null>(null),formVisible=ref(false),quantity=ref(''),reason=ref(''),recipient=ref(''),remark=ref(''),saving=ref(false);const title=computed(()=>kind.value==='inbound'?'入库管理':'出库管理');const total=computed(()=>list.value.reduce((s,x)=>s+Number(x.quantity),0));async function load(){loading.value=true;try{const [rows,base]=await Promise.all([cartonInventoryApi.traces(kind.value,{skuId:skuId.value,part:part.value,start:start.value,end:end.value}),cartonInventoryApi.overview()]);list.value=rows;options.value=base.options;error.value=''}catch(e){error.value=e instanceof Error?e.message:'出入库记录加载失败'}finally{loading.value=false;uni.stopPullDownRefresh()}}function reset(){skuId.value=0;part.value='';start.value='';end.value='';load()}async function submit(){const qty=Number(quantity.value);if(!skuId.value||!part.value||!Number.isInteger(qty)||qty<1)return uni.showToast({title:'请完整填写规格、分区和数量',icon:'none'});saving.value=true;try{if(kind.value==='inbound')await cartonInventoryApi.inbound({skuId:skuId.value,part:part.value,quantity:qty,reason:reason.value,remark:remark.value});else await cartonInventoryApi.outbound({skuId:skuId.value,part:part.value,quantity:qty,recipient:recipient.value,reasonType:0,remark:remark.value});formVisible.value=false;quantity.value='';reason.value='';recipient.value='';remark.value='';uni.showToast({title:'提交成功',icon:'success'});load()}finally{saving.value=false}}onLoad((q)=>{kind.value=q?.kind==='outbound'?'outbound':'inbound';load()});onPullDownRefresh(load);
</script>
<template><view class="page"><view class="top"><b>{{title}}</b><button @click="formVisible=true">＋{{kind==='inbound'?'新增入库':'手动出库'}}</button></view><view class="filters"><picker :range="['全部规格',...options.skus.map(x=>x.specification)]" @change="skuId=Number($event.detail.value)?options.skus[Number($event.detail.value)-1].sku_id:0"><view>{{options.skus.find(x=>x.sku_id===skuId)?.specification||'全部规格'}}⌄</view></picker><picker :range="['全部分区',...options.parts]" @change="part=Number($event.detail.value)?options.parts[Number($event.detail.value)-1]:''"><view>{{part||'全部分区'}}⌄</view></picker><picker mode="date" @change="start=$event.detail.value"><view>{{start||'开始日期'}}</view></picker><picker mode="date" @change="end=$event.detail.value"><view>{{end||'结束日期'}}</view></picker><button @click="reset">重置</button><button class="primary" @click="load">查询</button></view><view v-if="kind==='outbound'" class="summary"><view><text>总出库数量</text><b>{{total}}</b></view><view><text>成功记录</text><b>{{list.filter(x=>!x.outbound_failed).length}}</b></view><view><text>失败记录</text><b class="danger">{{list.filter(x=>x.outbound_failed).length}}</b></view></view><view class="section"><b>{{kind==='inbound'?'入库记录列表':'出库明细'}}</b></view><view class="head"><text>规格型号</text><text>分区</text><text>{{kind==='inbound'?'入库':'出库'}}数量</text><text>操作时间</text><text>操作</text></view><WareState v-if="loading||error||!list.length" :type="loading ? 'loading' : error ? 'error' : 'empty'" :title="loading ? '正在加载' : error ? '加载失败' : '暂无记录'" :description="error" :action-label="error ? '重新加载' : undefined" @action="load"/><view v-else class="row" v-for="x in list" :key="x.id"><b>{{x.specification}}</b><text>{{x.part}}</text><text>{{x.quantity}}{{x.unit_name}}</text><text>{{x.create_time}}</text><text class="link" @click="detail=x">查看详情</text></view><view v-if="formVisible" class="mask" @click="formVisible=false"><view class="drawer form" @click.stop><b>{{kind==='inbound'?'新增入库':'手动出库'}}</b><label>规格型号*</label><picker :range="options.skus.map(x=>x.specification)" @change="skuId=options.skus[Number($event.detail.value)].sku_id"><view class="input">{{options.skus.find(x=>x.sku_id===skuId)?.specification||'请选择规格型号'}}⌄</view></picker><label>分区选择*</label><picker :range="options.parts" @change="part=options.parts[Number($event.detail.value)]"><view class="input">{{part||'请选择分区'}}⌄</view></picker><label>{{kind==='inbound'?'入库原因':'领用人'}}*</label><input v-if="kind==='inbound'" v-model="reason" class="input" placeholder="请输入入库原因"/><input v-else v-model="recipient" class="input" placeholder="请输入领用人"/><label>{{kind==='inbound'?'入库':'出库'}}数量*</label><input v-model="quantity" class="input" type="number" placeholder="请输入数量"/><label>备注（选填）</label><textarea v-model="remark" placeholder="请输入备注信息"/><view class="drawer-actions"><button @click="formVisible=false">取消</button><button :disabled="saving" @click="submit">{{saving?'提交中…':'确认提交'}}</button></view></view></view><view v-if="detail" class="mask" @click="detail=null"><view class="drawer" @click.stop><b>基本信息</b><view class="detail-grid"><text>物资名称</text><b>{{detail.sku_name}}</b><text>规格型号</text><b>{{detail.specification}}</b><text>分区</text><b>{{detail.part}}</b><text>{{kind==='inbound'?'入库':'出库'}}数量</text><b>{{detail.quantity}}{{detail.unit_name}}</b><text>操作时间</text><b>{{detail.create_time}}</b><text>操作人</text><b>{{detail.operator_name}}</b><text>关联单号</text><b>{{detail.related_order||'--'}}</b><text>备注</text><b>{{detail.remark||'无'}}</b></view><button class="close" @click="detail=null">关闭</button></view></view></view></template>
<style scoped>.page{min-height:100vh;padding:20rpx;background:var(--wms-background)}.top{display:flex;align-items:center;justify-content:space-between}.top>b{font-size:29rpx}.top button{width:auto;margin:0;padding:0 18rpx;border-radius:8rpx;background:var(--wms-primary-700);color:#fff;font-size:19rpx;line-height:58rpx}.filters{display:grid;grid-template-columns:1fr 1fr;margin:14rpx -20rpx 0;padding:14rpx 20rpx;gap:9rpx;background:#fff}.filters picker view,.filters button{box-sizing:border-box;height:58rpx;margin:0;padding:0 12rpx;border:1rpx solid var(--wms-border);border-radius:8rpx;background:#fff;font-size:18rpx;line-height:58rpx}.filters button{background:#f0f2f2}.filters .primary{border:0;background:var(--wms-primary-700);color:#fff}.summary{display:grid;grid-template-columns:repeat(3,1fr);margin:12rpx -20rpx;background:#fff}.summary view{padding:18rpx;text-align:center}.summary text,.summary b{display:block}.summary text{font-size:18rpx;color:var(--wms-text-secondary)}.summary b{margin-top:5rpx;color:var(--wms-success);font-size:28rpx}.summary .danger{color:var(--wms-danger)}.section{margin:12rpx -20rpx 0;padding:16rpx 20rpx;background:#fff}.head,.row{display:grid;grid-template-columns:1.15fr .8fr .72fr 1fr .62fr;align-items:center;gap:6rpx;margin:0 -20rpx;padding:12rpx 20rpx}.head{color:var(--wms-text-secondary);font-size:16rpx}.row{min-height:74rpx;border-bottom:1rpx solid var(--wms-border);background:#fff;font-size:17rpx}.row b{font-size:18rpx}.link{color:var(--wms-primary-700)}.mask{position:fixed;z-index:80;inset:0;display:flex;align-items:flex-end;background:#0007}.drawer{box-sizing:border-box;min-height:56vh;width:100%;padding:26rpx 24rpx calc(24rpx + env(safe-area-inset-bottom));border-radius:24rpx 24rpx 0 0;background:#fff}.form{max-height:92vh;overflow:auto}.form>b,.drawer>b{font-size:27rpx}.form label{display:block;margin:18rpx 0 8rpx;font-size:20rpx}.input,.form textarea{box-sizing:border-box;width:100%;border:1rpx solid var(--wms-border);border-radius:8rpx;background:#fff;font-size:20rpx}.input{height:68rpx;padding:0 15rpx;line-height:68rpx}.form textarea{height:120rpx;padding:14rpx}.drawer-actions{display:grid;grid-template-columns:1fr 1fr;gap:12rpx;margin-top:24rpx}.drawer-actions button,.close{margin:0;border-radius:8rpx;font-size:21rpx}.drawer-actions button:last-child,.close{background:var(--wms-primary-700);color:#fff}.detail-grid{display:grid;grid-template-columns:150rpx 1fr;gap:15rpx;margin-top:24rpx;font-size:20rpx}.detail-grid text{color:var(--wms-text-secondary)}.detail-grid b{text-align:right}.close{position:absolute;right:24rpx;bottom:24rpx;left:24rpx;width:calc(100% - 48rpx)}</style>
